{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None), event("b", 1, False)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_and_ignores_empty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"a": []}) == 0.0


def test_flags_in_window():
    counts = [2, 0, 3, 4]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 1) == 4
    assert flags_in_window(counts, 2) == 7
    assert flags_in_window(counts, 10) == 9
    assert flags_in_window([], 3) == 0


def test_parse_fields_and_skip_blank_and_comment_lines():
    lines = ["\n", "   # comment, even with commas\n", " a , 3 , 1 ",
             "b, -2, 0", " c , 4 ,  ", "  "]
    assert parse_transcript_log(iter(lines)) == [
        event("a", 3, True), event("b", -2, False), event("c", 4, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,no"])
def test_parse_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_id_and_sorts_by_day_then_id():
    first = event("a", 5, True)
    last = event("a", 1, None)
    b = event("b", 1, False)
    c = event("c", 0, True)
    assert dedupe_transcripts([first, b, c, last]) == [c, last, b]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_with_gaps_and_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, True), event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 4)["recent"] == 2
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, True)], "a": [event("a", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["b", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, -1, 1]) == 3
    assert longest_flag_streak([0, -2, 0]) == 0
    assert longest_flag_streak([]) == 0
